import { Component } from '@angular/core';

@Component({
  selector: 'app-hero',
  templateUrl: './hero.component.html',
  styleUrls: ['./hero.component.css']
})
export class HeroComponent {

}
<section class="pixel-hero">
  <h1>Impulsa<br><span>tu Presencia Online</span><br>con Desavelopers</h1>
  <p class="sub">Expertos en Desarrollo Web & Diseño de Aplicaciones a Medida</p>
  <button class="pixel-btn">Empieza tu Proyecto Hoy</button>
</section>
